def etat_stock(casiers):
    """Renvoie l'état du stock d'une bière."""
    if casiers == 0:
        etat = "Rupture de stock"
    elif casiers < 10:
        etat = "Stock bas"
    else:
        etat = "Stock suffisant"
    return etat

